"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties, KeyboardEvent } from "react";
import { useState } from "react";
import type { FilterBarKnobStyle } from "@/components/control-ui/knob-contracts/filter-bar-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { FilterBarContext, type FilterBarContextValue, type FilterBarExit } from "./filter-bar/context";
import { defaultFilterBarLabels, describeFilter, fieldOperators, filterNavigationKeys } from "./filter-bar/model";
import { filterMotionEnabled, useFilterBarMotion } from "./filter-bar/motion";
import { FilterBarAddButton, FilterBarChip, FilterBarChips, FilterBarClear, FilterBarInput } from "./filter-bar/parts";
import type {
  FilterBarDraft,
  FilterBarField,
  FilterBarItem,
  FilterBarLabels,
  FilterBarOperator,
  FilterBarStage,
  FilterBarValue,
} from "./filter-bar/types";

export type {
  FilterBarAddButtonProps,
  FilterBarChipProps,
  FilterBarChipsProps,
  FilterBarClearProps,
  FilterBarInputProps,
} from "./filter-bar/parts";
export type {
  FilterBarField,
  FilterBarFieldType,
  FilterBarItem,
  FilterBarLabels,
  FilterBarOperator,
  FilterBarOption,
  FilterBarQuery,
  FilterBarScalar,
  FilterBarStage,
  FilterBarValue,
} from "./filter-bar/types";

export type FilterBarRootProps = Omit<ComponentProps<"fieldset">, "onChange" | "style" | "defaultValue"> & {
  fields: readonly FilterBarField[];
  operators: readonly FilterBarOperator[];
  value?: readonly FilterBarItem[];
  defaultValue?: readonly FilterBarItem[];
  onValueChange?: (value: FilterBarItem[]) => void;
  labels?: Partial<FilterBarLabels>;
  createItemId?: () => string;
  disabled?: boolean;
  readOnly?: boolean;
  style?: CSSProperties & FilterBarKnobStyle;
};

function valueStatusMessage(field: FilterBarField | undefined, labels: FilterBarLabels): string | undefined {
  if (field?.error) return typeof field.error === "string" ? field.error : labels.loadError;
  if (field?.loading) return labels.loading;
  return undefined;
}

let fallbackItemCount = 0;

/** Swapping "is" for "is not" on a chip must not cost the value already picked; only a different arity needs a new one. */
function valuesKeptByOperator(draft: FilterBarDraft, operator: FilterBarOperator, operators: readonly FilterBarOperator[]) {
  const previous = operators.find((candidate) => candidate.id === draft.operatorId);
  return previous && (previous.arity ?? "one") === (operator.arity ?? "one") ? draft.values : [];
}

function createFilterItemId() {
  // randomUUID only exists in secure contexts; plain-http origins still need unique chip ids.
  if (typeof crypto.randomUUID === "function") return crypto.randomUUID();
  fallbackItemCount += 1;
  return `filter-${Date.now().toString(36)}-${fallbackItemCount}`;
}

function FilterBarRoot({
  fields,
  operators,
  value,
  defaultValue = [],
  onValueChange,
  labels,
  createItemId = createFilterItemId,
  disabled = false,
  readOnly = false,
  className,
  children,
  ref,
  "aria-label": ariaLabel = "Filters",
  ...props
}: FilterBarRootProps) {
  const [uncontrolledItems, setUncontrolledItems] = useState(defaultValue);
  const items = value ?? uncontrolledItems;
  const text = { ...defaultFilterBarLabels, ...labels };
  const [draft, setDraft] = useState<FilterBarDraft | null>(null);
  const [exits, setExits] = useState<FilterBarExit[]>([]);
  const [announcement, setAnnouncement] = useState({ message: "", key: 0 });
  const [focusNodes] = useState(() => new Map<string, HTMLElement>());
  const { rootRef, ...motion } = useFilterBarMotion();

  function register(key: string, element: HTMLElement | null) {
    if (key.startsWith("chip:") || key.startsWith("entry:")) motion.register(key, element);
    if (element) focusNodes.set(key, element);
    else focusNodes.delete(key);
  }

  function setItems(next: FilterBarItem[]) {
    if (value === undefined) setUncontrolledItems(next);
    onValueChange?.(next);
  }

  // Removing the same filter twice produces the same sentence; the key makes the live region speak it again.
  function announce(message: string) {
    setAnnouncement((current) => ({ message, key: current.key + 1 }));
  }

  function transition(next: FilterBarDraft) {
    motion.capture();
    setAnnouncement((current) => ({ ...current, message: "" }));
    setDraft(next);
    if (next.stage !== "value" || !next.fieldId || !next.operatorId) return;
    const sameRequest =
      draft?.stage === "value" &&
      draft.id === next.id &&
      draft.fieldId === next.fieldId &&
      draft.operatorId === next.operatorId &&
      draft.query === next.query;
    if (sameRequest) return;
    fields
      .find((field) => field.id === next.fieldId)
      ?.onQueryChange?.({ fieldId: next.fieldId, operatorId: next.operatorId, query: next.query });
  }

  function start(owner: string, anchor: HTMLElement, stage: FilterBarStage = "field", item?: FilterBarItem, initialQuery?: string) {
    if (disabled || readOnly) return;
    if (draft?.owner === owner && draft.stage === stage) return;
    const values = item?.value === null || item?.value === undefined ? [] : [item.value].flat();
    const query = initialQuery ?? "";
    transition({
      id: item?.id ?? createItemId(),
      owner,
      anchor,
      stage,
      fieldId: item?.fieldId,
      operatorId: item?.operatorId,
      values,
      query,
      editing: Boolean(item),
    });
  }

  function close(restoreFocus = true) {
    motion.capture();
    if (restoreFocus && draft?.anchor.isConnected) draft.anchor.focus();
    setDraft(null);
  }

  function back() {
    if (!draft) return;
    if (draft.stage === "field") return close();
    if (draft.stage === "operator") return transition({ ...draft, stage: "field", operatorId: undefined, values: [], query: "" });
    const field = fields.find((candidate) => candidate.id === draft.fieldId);
    const stage = field && fieldOperators(field, operators).length === 1 ? "field" : "operator";
    transition({ ...draft, stage, values: [], query: "" });
  }

  function setQuery(query: string) {
    if (!draft) return;
    setDraft({ ...draft, query });
    if (draft.stage === "value" && draft.fieldId && draft.operatorId) {
      fields.find((field) => field.id === draft.fieldId)?.onQueryChange?.({ fieldId: draft.fieldId, operatorId: draft.operatorId, query });
    }
  }

  function commitDraft(next: FilterBarDraft, nextValue: FilterBarValue) {
    if (disabled || readOnly) return;
    if (!next.fieldId || !next.operatorId) return;
    const item: FilterBarItem = { id: next.id, fieldId: next.fieldId, operatorId: next.operatorId, value: nextValue };
    motion.capture();
    setItems(next.editing ? items.map((current) => (current.id === item.id ? item : current)) : [...items, item]);
    announce((next.editing ? text.updated : text.added)(describeFilter(item, fields, operators)));
    if (next.anchor.isConnected) next.anchor.focus();
    setDraft(null);
  }

  function selectOperator(operatorId: string, next = draft) {
    const operator = operators.find((candidate) => candidate.id === operatorId);
    if (!next || !operator) return;
    const values = valuesKeptByOperator(next, operator, operators);
    const nextDraft: FilterBarDraft = { ...next, operatorId, stage: "value", values, query: "" };
    if (operator.arity === "none") commitDraft(nextDraft, null);
    else if (values.length === 0) transition(nextDraft);
    else commitDraft(nextDraft, operator.arity === "many" ? values : (values[0] ?? null));
  }

  function selectField(fieldId: string) {
    if (!draft) return;
    const field = fields.find((candidate) => candidate.id === fieldId);
    if (!field) return;
    const available = fieldOperators(field, operators);
    const next: FilterBarDraft = { ...draft, fieldId, operatorId: undefined, stage: "operator", values: [], query: "" };
    if (available.length === 1 && available[0]) selectOperator(available[0].id, next);
    else transition(next);
  }

  function addExits(leavingItems: readonly FilterBarItem[]) {
    const root = rootRef.current;
    if (!root || !filterMotionEnabled(root)) return;
    const rootBounds = root.getBoundingClientRect();
    const leaving = leavingItems.flatMap((item) => {
      const node = focusNodes.get(`chip:${item.id}`);
      if (!node) return [];
      const bounds = node.getBoundingClientRect();
      return [
        {
          item,
          style: {
            position: "absolute",
            left: bounds.left - rootBounds.left,
            top: bounds.top - rootBounds.top,
            width: bounds.width,
            height: bounds.height,
          },
        } satisfies FilterBarExit,
      ];
    });
    setExits((current) => [...current, ...leaving]);
  }

  function focusEntry() {
    const entry = [...focusNodes].find(([key]) => key.startsWith("entry:"));
    entry?.[1].focus();
  }

  function remove(item: FilterBarItem, moveFocus = true) {
    if (disabled || readOnly) return;
    motion.capture();
    addExits([item]);
    if (moveFocus) {
      const index = items.findIndex((candidate) => candidate.id === item.id);
      const neighbour = items[index + 1] ?? items[index - 1];
      const target = neighbour ? focusNodes.get(`${neighbour.id}:field`) : undefined;
      if (target) target.focus();
      else focusEntry();
    }
    if (draft?.id === item.id) setDraft(null);
    setItems(items.filter((candidate) => candidate.id !== item.id));
    announce(text.removed(describeFilter(item, fields, operators)));
  }

  function clear() {
    if (disabled || readOnly) return;
    motion.capture();
    addExits(items);
    setDraft(null);
    setItems([]);
    focusEntry();
    announce(text.cleared);
  }

  function deleteFocusedFilter(event: KeyboardEvent<HTMLElement>, itemId: string) {
    const item = items.find((candidate) => candidate.id === itemId);
    if (!item) return;
    event.preventDefault();
    remove(item);
  }

  function focusAdjacentFilter(event: KeyboardEvent<HTMLElement>, itemId?: string, part?: string) {
    const keys = filterNavigationKeys(items).filter((key) => focusNodes.has(key));
    const index = itemId ? keys.indexOf(`${itemId}:${part}`) : keys.length;
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
    const direction = (event.key === "ArrowLeft") === rtl ? 1 : -1;
    const target = keys[index + direction];
    event.preventDefault();
    if (target) focusNodes.get(target)?.focus();
    else if (itemId) focusEntry();
  }

  function navigate(event: KeyboardEvent<HTMLElement>, itemId?: string, part?: string) {
    if (event.defaultPrevented) return;
    const removing = event.key === "Delete" || event.key === "Backspace";
    if (itemId && removing) return deleteFocusedFilter(event, itemId);
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") focusAdjacentFilter(event, itemId, part);
  }

  const context: FilterBarContextValue = {
    fields,
    operators,
    labels: text,
    items,
    draft,
    exits,
    disabled,
    readOnly,
    register,
    start,
    close,
    back,
    setQuery,
    selectField,
    selectOperator,
    selectValues: (values) => {
      if (draft) transition({ ...draft, values, query: "" });
    },
    commit: (nextValue) => {
      if (draft) commitDraft(draft, nextValue);
    },
    remove,
    clear,
    releaseExit: (id) => setExits((current) => current.filter((exit) => exit.item.id !== id)),
    navigate,
  };

  const draftField = draft?.stage === "value" ? fields.find((field) => field.id === draft.fieldId) : undefined;
  const liveMessage = valueStatusMessage(draftField, text) ?? announcement.message;

  const rootElement = useRender({
    ref: [rootRef, ref ?? null],
    render: (
      <fieldset
        aria-label={ariaLabel}
        data-control-ui="filter-bar"
        data-control-family="filter-bar"
        data-slot="root"
        data-disabled={disabled || undefined}
        data-readonly={readOnly || undefined}
        className={cn("relative flex min-w-0 flex-wrap items-center", className)}
        {...props}
      >
        {children}
        <LiveStatus message={liveMessage} announcementKey={announcement.key} />
      </fieldset>
    ),
  });
  return <FilterBarContext.Provider value={context}>{rootElement}</FilterBarContext.Provider>;
}

export const FilterBar = {
  Root: FilterBarRoot,
  Chips: FilterBarChips,
  Chip: FilterBarChip,
  AddButton: FilterBarAddButton,
  Input: FilterBarInput,
  Clear: FilterBarClear,
};

export const DEFAULT_FILTER_OPERATORS: readonly FilterBarOperator[] = [
  { id: "is", label: "is" },
  { id: "is-not", label: "is not" },
  { id: "contains", label: "contains", types: ["text"] },
  { id: "starts-with", label: "starts with", types: ["text"] },
  { id: "gt", label: ">", ariaLabel: "greater than", types: ["number"] },
  { id: "gte", label: "≥", ariaLabel: "at least", types: ["number"] },
  { id: "lt", label: "<", ariaLabel: "less than", types: ["number"] },
  { id: "lte", label: "≤", ariaLabel: "at most", types: ["number"] },
  { id: "in", label: "is any of", arity: "many", types: ["text", "number"] },
  { id: "is-empty", label: "is empty", arity: "none" },
  { id: "is-not-empty", label: "is not empty", arity: "none" },
];

"use client";

import type { CSSProperties, KeyboardEvent } from "react";
import { createContext, use } from "react";
import type {
  FilterBarDraft,
  FilterBarField,
  FilterBarItem,
  FilterBarLabels,
  FilterBarOperator,
  FilterBarScalar,
  FilterBarStage,
  FilterBarValue,
} from "./types";

export type FilterBarExit = { item: FilterBarItem; style: CSSProperties };

export type FilterBarContextValue = {
  fields: readonly FilterBarField[];
  operators: readonly FilterBarOperator[];
  labels: FilterBarLabels;
  items: readonly FilterBarItem[];
  draft: FilterBarDraft | null;
  exits: FilterBarExit[];
  disabled: boolean;
  readOnly: boolean;
  register: (key: string, element: HTMLElement | null) => void;
  start: (owner: string, anchor: HTMLElement, stage?: FilterBarStage, item?: FilterBarItem, query?: string) => void;
  close: (restoreFocus?: boolean) => void;
  back: () => void;
  setQuery: (query: string) => void;
  selectField: (fieldId: string) => void;
  selectOperator: (operatorId: string) => void;
  selectValues: (values: FilterBarScalar[]) => void;
  commit: (value: FilterBarValue) => void;
  remove: (item: FilterBarItem, moveFocus?: boolean) => void;
  clear: () => void;
  releaseExit: (id: string) => void;
  navigate: (event: KeyboardEvent<HTMLElement>, itemId?: string, part?: string) => void;
};

export const FilterBarContext = createContext<FilterBarContextValue | null>(null);

export function useFilterBarContext() {
  const context = use(FilterBarContext);
  if (!context) throw new Error("FilterBar parts must be used inside FilterBar.Root.");
  return context;
}

"use client";

import type { KeyboardEvent, ReactNode, Ref, RefObject } from "react";
import { useRef } from "react";
import type { OpenChangeEventDetails } from "@/components/control-ui/control-props";
import { Button } from "@/components/control-ui/ui/button";
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  type ComboboxInputProps,
  ComboboxItem,
  ComboboxList,
} from "@/components/control-ui/ui/combobox";
import { Text } from "@/components/control-ui/ui/typography";
import { type FilterBarContextValue, useFilterBarContext } from "./context";
import { allowsCustomValue, fieldOperators, fieldOptions, parseCustomValue } from "./model";
import type { FilterBarDraft, FilterBarField, FilterBarLabels, FilterBarScalar, FilterBarStage } from "./types";

type FilterChoice = { id: string; label: string; ariaLabel?: string; icon?: ReactNode; value?: FilterBarScalar; disabled?: boolean };

function valueChoice(value: FilterBarScalar, label: string): FilterChoice {
  return { id: `${typeof value}:${value}`, value, label };
}

function sameChoice(first: FilterChoice, second: FilterChoice) {
  return first.id === second.id;
}

function valueChoices(field: FilterBarField, query: string, labels: FilterBarLabels) {
  const choices: FilterChoice[] = fieldOptions(field).map((option) => ({
    ...valueChoice(option.value, option.label),
    icon: option.icon,
    disabled: option.disabled,
  }));
  const customValue = allowsCustomValue(field) ? parseCustomValue(field, query) : undefined;
  if (customValue !== undefined && !choices.some((choice) => choice.value === customValue))
    choices.push(valueChoice(customValue, labels.customValue(String(customValue))));
  return choices;
}

function editorChoices(context: FilterBarContextValue, draft: FilterBarDraft | null): FilterChoice[] {
  if (!draft || draft.stage === "field")
    return context.fields
      .filter((candidate) => fieldOperators(candidate, context.operators).length > 0)
      .map((candidate) => ({ id: candidate.id, label: candidate.label, icon: candidate.icon }));
  const field = context.fields.find((candidate) => candidate.id === draft.fieldId);
  if (!field) return [];
  if (draft.stage === "operator")
    return fieldOperators(field, context.operators).map((operator) => ({
      id: operator.id,
      label: operator.label,
      ariaLabel: operator.ariaLabel,
    }));
  return valueChoices(field, draft.query, context.labels);
}

function searchLabel(stage: FilterBarStage, field: FilterBarField | undefined, labels: FilterBarLabels) {
  if (stage === "field") return labels.fieldSearch;
  if (stage === "operator") return labels.operatorSearch;
  return labels.valueSearch(field?.label);
}

function statusId(owner: string) {
  return `${owner}-filter-status`;
}

function handleSelection(context: FilterBarContextValue, draft: FilterBarDraft | null, choice: FilterChoice | FilterChoice[] | null) {
  if (!choice || !draft) return;
  const field = context.fields.find((candidate) => candidate.id === draft.fieldId);
  if (draft.stage === "value" && (field?.loading || field?.error)) return;
  if (Array.isArray(choice)) context.selectValues(choice.flatMap((selected) => (selected.value === undefined ? [] : [selected.value])));
  else if (draft.stage === "field") context.selectField(choice.id);
  else if (draft.stage === "operator") context.selectOperator(choice.id);
  else if (choice.value !== undefined) context.commit(choice.value);
}

function handleEditorKeyDown(context: FilterBarContextValue, draft: FilterBarDraft | null, event: KeyboardEvent<HTMLInputElement>) {
  if (event.nativeEvent.isComposing) return false;
  const backwards = event.key === "Escape" || (event.key === "Backspace" && draft?.query === "");
  if (draft && backwards) {
    event.preventDefault();
    event.stopPropagation();
    context.back();
    return true;
  }
  const operator = context.operators.find((candidate) => candidate.id === draft?.operatorId);
  const field = context.fields.find((candidate) => candidate.id === draft?.fieldId);
  const committing = draft?.stage === "value" && operator?.arity === "many" && event.key === "Enter" && (event.metaKey || event.ctrlKey);
  if (!committing || !draft || draft.values.length === 0 || field?.loading || field?.error) return false;
  event.preventDefault();
  context.commit(draft.values);
  return true;
}

function emptyMessage(stage: FilterBarStage, field: FilterBarField | undefined, query: string, labels: FilterBarLabels) {
  if (stage !== "value" || !field || !allowsCustomValue(field) || parseCustomValue(field, query) !== undefined) return labels.noOptions;
  if (field.type === "number") return labels.invalidNumber;
  return query.trim() === "" ? labels.typeValue : labels.noOptions;
}

function statusContent(field: FilterBarField, labels: FilterBarLabels): ReactNode {
  if (!field.error) return labels.loading;
  return field.error === true ? labels.loadError : field.error;
}

function EditorOptions({ field, empty, owner }: { field?: FilterBarField; empty: string; owner: string }) {
  const { labels } = useFilterBarContext();
  if (field?.loading || field?.error)
    return (
      <Text as="div" size="caption" id={statusId(owner)} className="p-3">
        {statusContent(field, labels)}
      </Text>
    );
  return (
    <>
      <ComboboxEmpty>{empty}</ComboboxEmpty>
      <ComboboxList<FilterChoice>>
        {(choice) => (
          <ComboboxItem key={choice.id} value={choice} disabled={choice.disabled} aria-label={choice.ariaLabel}>
            <span className="flex min-w-0 items-center gap-2">
              {choice.icon}
              <span className="truncate" title={choice.label}>
                {choice.label}
              </span>
            </span>
          </ComboboxItem>
        )}
      </ComboboxList>
    </>
  );
}

function handleOpenChange(
  context: FilterBarContextValue,
  draft: FilterBarDraft | null,
  anchorRef: RefObject<HTMLInputElement | null> | undefined,
  owner: string,
  open: boolean,
  eventDetails: OpenChangeEventDetails,
) {
  if (open && !draft && anchorRef?.current && eventDetails.reason !== "input-change") context.start(owner, anchorRef.current);
  if (open || !draft) return;
  if (eventDetails.reason === "item-press" || eventDetails.reason === "escape-key") eventDetails.cancel();
  else context.close(false);
}

function editorView(context: FilterBarContextValue, draft: FilterBarDraft | null) {
  const field = context.fields.find((candidate) => candidate.id === draft?.fieldId);
  const operator = context.operators.find((candidate) => candidate.id === draft?.operatorId);
  const stage = draft?.stage ?? "field";
  const many = stage === "value" && operator?.arity === "many";
  const query = draft?.query ?? "";
  const choices = editorChoices(context, draft);
  const selected = (draft?.values ?? []).map(
    (value) => choices.find((choice) => choice.value === value) ?? valueChoice(value, field?.formatValue?.(value) ?? String(value)),
  );
  const empty = emptyMessage(stage, field, query, context.labels);
  const remote = stage === "value" && field?.optionsMode === "remote";
  const unavailable = stage === "value" && Boolean(field?.loading || field?.error);
  const label = searchLabel(stage, field, context.labels);
  const described = stage === "value" && Boolean(field?.error);
  return { field, stage, many, query, choices, selected, empty, remote, unavailable, label, described };
}

export function FilterBarEditor({
  owner,
  mode,
  anchorRef,
  children,
}: {
  owner: string;
  mode: "input" | "button";
  anchorRef?: RefObject<HTMLInputElement | null>;
  children: ReactNode;
}) {
  const context = useFilterBarContext();
  const searchRef = useRef<HTMLInputElement>(null);
  const draft = context.draft?.owner === owner ? context.draft : null;
  const { field, stage, many, query, choices, selected, empty, remote, unavailable, label, described } = editorView(context, draft);

  const canCommitMany = selected.length > 0 && !unavailable && !context.disabled && !context.readOnly;

  return (
    <Combobox<FilterChoice, boolean>
      items={choices}
      multiple={many}
      value={many ? selected : null}
      inputValue={query}
      open={draft !== null}
      disabled={context.disabled}
      readOnly={context.readOnly}
      modal={false}
      isItemEqualToValue={sameChoice}
      filter={remote ? null : undefined}
      onValueChange={(choice) => handleSelection(context, draft, choice)}
      onInputValueChange={(nextQuery, eventDetails) => {
        if (eventDetails.reason !== "input-change" && eventDetails.reason !== "input-clear") return;
        if (draft) context.setQuery(nextQuery);
        else if (anchorRef?.current) context.start(owner, anchorRef.current, "field", undefined, nextQuery);
      }}
      onOpenChange={(open, eventDetails) => handleOpenChange(context, draft, anchorRef, owner, open, eventDetails)}
    >
      {children}
      <ComboboxContent
        anchor={draft?.anchor}
        initialFocus={mode === "input" ? false : searchRef}
        finalFocus={false}
        className="w-72 max-h-(--available-height) overflow-y-auto"
        onKeyDown={(event) => {
          if (event.key === "Escape" && !event.defaultPrevented) {
            event.preventDefault();
            context.back();
          }
        }}
      >
        {mode === "button" && (
          <div className="p-2">
            <ComboboxInput
              ref={searchRef}
              size="sm"
              aria-label={label}
              aria-describedby={described ? statusId(owner) : undefined}
              placeholder={label}
              inputMode={field?.type === "number" && stage === "value" ? "decimal" : undefined}
              onKeyDown={(event) => handleEditorKeyDown(context, draft, event)}
            />
          </div>
        )}
        <EditorOptions field={stage === "value" ? field : undefined} empty={empty} owner={owner} />
        {many && (
          <div className="flex justify-end p-2">
            <Button disabled={!canCommitMany} onClick={() => context.commit(draft?.values ?? [])}>
              {context.labels.apply}
            </Button>
          </div>
        )}
      </ComboboxContent>
    </Combobox>
  );
}

export function FilterBarInlineInput({
  owner,
  inputRef,
  className,
  ...props
}: Omit<ComboboxInputProps, "ref"> & { owner: string; inputRef: Ref<HTMLInputElement> }) {
  const context = useFilterBarContext();
  const draft = context.draft?.owner === owner ? context.draft : null;
  const { label, described } = editorView(context, draft);
  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    props.onKeyDown?.(event);
    if (event.defaultPrevented || event.nativeEvent.isComposing) return;
    if (handleEditorKeyDown(context, draft, event) || event.currentTarget.value !== "") return;
    const last = context.items.at(-1);
    if (event.key === "Backspace" && !draft && last) {
      event.preventDefault();
      context.remove(last, false);
    } else context.navigate(event);
  }
  return (
    <ComboboxInput
      ref={inputRef}
      size="sm"
      className={className}
      {...props}
      aria-label={draft ? label : props["aria-label"]}
      aria-describedby={described ? statusId(owner) : props["aria-describedby"]}
      onKeyDown={handleKeyDown}
    />
  );
}

import type { FilterBarField, FilterBarItem, FilterBarLabels, FilterBarOperator, FilterBarOption, FilterBarScalar } from "./types";

export const defaultFilterBarLabels: FilterBarLabels = {
  fieldSearch: "Filter field",
  operatorSearch: "Filter operator",
  valueSearch: (fieldLabel) => `${fieldLabel ?? "Filter"} value`,
  operatorPlaceholder: "Operator…",
  valuePlaceholder: "Value…",
  editSegment: (stage, label) => `Edit ${stage}: ${label}`,
  removeFilter: (filter) => `Remove filter: ${filter}`,
  loading: "Loading values…",
  loadError: "Couldn’t load values.",
  noOptions: "No matching options.",
  typeValue: "Type a value.",
  invalidNumber: "Enter a number, like 42 or 3.5.",
  customValue: (value) => `Use “${value}”`,
  apply: "Apply",
  added: (filter) => `Added filter: ${filter}`,
  updated: (filter) => `Updated filter: ${filter}`,
  removed: (filter) => `Removed filter: ${filter}`,
  cleared: "Cleared all filters",
};

const booleanOptions = [
  { value: true, label: "True" },
  { value: false, label: "False" },
];

export function fieldOperators(field: FilterBarField, operators: readonly FilterBarOperator[]) {
  const allowed = field.operators;
  if (allowed) return operators.filter((operator) => allowed.includes(operator.id));
  const type = field.type ?? "text";
  return operators.filter((operator) => !operator.types || operator.types.includes(type));
}

export function fieldOptions(field: FilterBarField): readonly FilterBarOption[] {
  return field.options ?? (field.type === "boolean" ? booleanOptions : []);
}

export function parseCustomValue(field: FilterBarField, query: string): FilterBarScalar | undefined {
  if (!query.trim()) return undefined;
  if (field.type === "number") {
    if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(query.trim())) return undefined;
    const number = Number(query);
    return Number.isFinite(number) ? number : undefined;
  }
  if (field.type === "boolean") {
    if (query.toLowerCase() === "true") return true;
    if (query.toLowerCase() === "false") return false;
    return undefined;
  }
  return query.trim();
}

export function allowsCustomValue(field: FilterBarField) {
  return field.allowCustomValue ?? (field.options === undefined && field.type !== "boolean" && field.optionsMode !== "remote");
}

export function formatFilterValue(item: FilterBarItem, field: FilterBarField | undefined) {
  if (item.value === null) return "";
  const values = Array.isArray(item.value) ? item.value : [item.value];
  return values.map((value) => field?.formatValue?.(value) ?? fieldOptionsForLabel(field, value)).join(", ");
}

function fieldOptionsForLabel(field: FilterBarField | undefined, value: FilterBarScalar) {
  return (field ? fieldOptions(field).find((option) => option.value === value)?.label : undefined) ?? String(value);
}

export function describeFilter(item: FilterBarItem, fields: readonly FilterBarField[], operators: readonly FilterBarOperator[]) {
  const field = fields.find((candidate) => candidate.id === item.fieldId);
  const operator = operators.find((candidate) => candidate.id === item.operatorId);
  return [field?.label ?? item.fieldId, operator?.ariaLabel ?? operator?.label, formatFilterValue(item, field)].filter(Boolean).join(" ");
}

export function filterNavigationKeys(items: readonly FilterBarItem[]) {
  return items.flatMap((item) =>
    ["field", "operator", ...(item.value === null ? [] : ["value"]), "remove"].map((segment) => `${item.id}:${segment}`),
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import { prefersReducedMotion, readDurationMs } from "@/components/control-ui/lib/motion";

export function filterMotionEnabled(element: HTMLElement) {
  return !prefersReducedMotion(element) && readDurationMs(element, "--duration-fast") > 0;
}

function animateMovement(element: HTMLElement, before: DOMRect, after: DOMRect, duration: number, easing: string) {
  const x = before.left - after.left;
  const y = before.top - after.top;
  if (Math.abs(x) < 1 && Math.abs(y) < 1) return null;
  return element.animate([{ transform: `translate(${x}px, ${y}px)` }, { transform: "translate(0, 0)" }], { duration, easing });
}

function animateLayout(
  elements: Map<string, HTMLElement>,
  before: Map<string, DOMRect>,
  after: Map<string, DOMRect>,
  animations: Map<string, Animation>,
  duration: number,
  easing: string,
) {
  for (const [key, bounds] of after) {
    const origin = before.get(key);
    const element = elements.get(key);
    if (!origin || !element) continue;
    const animation = animateMovement(element, origin, bounds, duration, easing);
    if (animation) animations.set(key, animation);
  }
}

export function useFilterBarMotion() {
  const rootRef = useRef<HTMLFieldSetElement>(null);
  const [motion] = useState(() => {
    const elements = new Map<string, HTMLElement>();
    const animations = new Map<string, Animation>();
    let captured: Map<string, DOMRect> | null = null;

    function measure() {
      return new Map([...elements].map(([key, element]) => [key, element.getBoundingClientRect()]));
    }

    function cancel() {
      for (const animation of animations.values()) animation.cancel();
      animations.clear();
    }

    return {
      register(key: string, element: HTMLElement | null) {
        if (element) elements.set(key, element);
        else elements.delete(key);
      },
      capture() {
        captured = measure();
      },
      cancel,
      play() {
        if (!captured) return;
        const origin = captured;
        captured = null;
        cancel();
        const root = rootRef.current;
        if (!root || !filterMotionEnabled(root)) return;
        const next = measure();
        const duration = readDurationMs(root, "--duration-fast");
        const easing = getComputedStyle(root).getPropertyValue("--ease-standard").trim();
        animateLayout(elements, origin, next, animations, duration, easing);
      },
    };
  });

  useLayoutEffect(() => motion.play());
  useLayoutEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    function cancelReducedMotion() {
      if (media.matches) motion.cancel();
    }
    media.addEventListener("change", cancelReducedMotion);
    return () => {
      media.removeEventListener("change", cancelReducedMotion);
      motion.cancel();
    };
  }, [motion]);
  return { rootRef, ...motion };
}

